def create_default_profiles(apps, schema_editor):
    """Each unit with a support template gets a "Default" profile (premium
    blank = unit default, so every figure is unchanged); its members move into
    it and the unit's jobs point at it."""
    OrganisationalUnit = apps.get_model("jobtracker", "OrganisationalUnit")
    SupportProfile = apps.get_model("jobtracker", "SupportProfile")
    Member = apps.get_model("jobtracker", "OrganisationalUnitSupportTemplateMember")
    Job = apps.get_model("jobtracker", "Job")
    unit_ids = Member.objects.values_list("unit_id", flat=True).distinct()
    for unit in OrganisationalUnit.objects.filter(pk__in=list(unit_ids)):
        profile = SupportProfile.objects.create(
            unit=unit, name="Default", is_default=True
        )
        Member.objects.filter(unit=unit).update(profile=profile)
        Job.objects.filter(unit=unit).update(support_profile=profile)


